do $$
declare
  v_missing integer;
begin
  select count(*)
  into v_missing
  from (values
    ('Oeiras Challenger'), ('Palm Springs Challenger'), ('Itajaí Challenger'), ('Soma Bay Challenger'),
    ('Phan Thiết Challenger'), ('Antalya Futures'), ('Santiago Futures'), ('Monastir Futures'),
    ('Manama Challenger'), ('Quimper Challenger'), ('Concepción Challenger'), ('Fujairah Challenger'),
    ('San Diego Challenger'), ('Christchurch Challenger'), ('Porto Challenger'), ('Bình Thuận Challenger'),
    ('Sharm El-Sheikh Futures')
  ) as expected(name)
  left join public.tournament_series s on s.name = expected.name and s.logo_url is not null
  where s.id is null;

  if v_missing <> 0 then
    raise exception 'Some January tournament logo assignments failed: % missing', v_missing;
  end if;
end $$;
